-- Synthetic orders only. No payments, messages, model calls or durable fixtures.
begin;
do $$
declare u uuid:=gen_random_uuid(); v uuid:=gen_random_uuid(); a uuid:=gen_random_uuid();
 o jsonb; again jsonb; order_id uuid; expiry timestamptz; prior timestamptz; r uuid; response jsonb; checks integer:=0; n integer;
begin
 insert into auth.users(id,email,email_confirmed_at) values
 (u,'member-'||u||'@example.invalid',now()),(v,'visitor-'||v||'@example.invalid',now()),(a,'reviewer-'||a||'@example.invalid',now());
 insert into public.rp_membership_admins values(a);
 perform set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true);
 o:=public.rp_membership_create_order(); order_id:=(o->>'id')::uuid;
 if o->>'status'<>'awaiting_payment' or (o->>'amount_fen')::integer<>1290 then raise exception 'wrong initial order'; end if; checks:=checks+1;
 again:=public.rp_membership_create_order();
 if again->>'id'<>o->>'id' then raise exception 'duplicate pending order'; end if; checks:=checks+1;
 if (select member_until is not null from public.rp_ai_wallets where user_id=u) then raise exception 'creation activated access'; end if; checks:=checks+1;
 begin perform public.rp_membership_submit_order(order_id,now()+interval '1 hour','123456');raise exception 'future payment accepted';exception when raise_exception then if sqlerrm<>'INVALID_PAYMENT_TIME' then raise;end if;end;checks:=checks+1;
 perform set_config('request.jwt.claims',json_build_object('sub',v,'role','authenticated')::text,true);
 begin perform public.rp_membership_submit_order(order_id,now(),'123456');raise exception 'cross owner submission';exception when raise_exception then if sqlerrm<>'ORDER_NOT_FOUND' then raise;end if;end;checks:=checks+1;
 perform set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true);
 o:=public.rp_membership_submit_order(order_id,now(),'123456');
 if o->>'status'<>'submitted' or (select member_until is not null from public.rp_ai_wallets where user_id=u) then raise exception 'submission activated';end if;checks:=checks+1;
 begin perform public.rp_membership_review_order(v,order_id,true,1290,'');raise exception 'unapproved reviewer';exception when raise_exception then if sqlerrm<>'ADMIN_REQUIRED' then raise;end if;end;checks:=checks+1;
 begin perform public.rp_membership_review_order(a,order_id,true,1,'');raise exception 'wrong amount allowed';exception when raise_exception then if sqlerrm<>'PAYMENT_AMOUNT_MISMATCH' then raise;end if;end;checks:=checks+1;
 begin perform public.rp_membership_review_order(a,order_id,true,null,'');raise exception 'null amount allowed';exception when raise_exception then if sqlerrm<>'PAYMENT_AMOUNT_MISMATCH' then raise;end if;end;checks:=checks+1;
 begin perform public.rp_membership_review_order(a,order_id,null,1290,'');raise exception 'null approval allowed';exception when raise_exception then if sqlerrm<>'INVALID_REVIEW' then raise;end if;end;checks:=checks+1;
 o:=public.rp_membership_review_order(a,order_id,false,0,'请补充备注');
 if o->>'status'<>'needs_info' then raise exception 'missing information failed';end if;
 o:=public.rp_membership_submit_order(order_id,now(),'654321');
 if o->>'status'<>'submitted' or o->>'payment_reference'<>'654321' then raise exception 'resubmission failed';end if;checks:=checks+1;
 o:=public.rp_membership_review_order(a,order_id,true,1290,'synthetic receipt');
 select member_until into expiry from public.rp_ai_wallets where user_id=u;
 if o->>'status'<>'approved' or expiry<>(((now() at time zone 'Asia/Shanghai')+interval '1 month') at time zone 'Asia/Shanghai') then raise exception 'activation term incorrect';end if;checks:=checks+1;
 perform public.rp_membership_review_order(a,order_id,true,1290,'replay');
 if (select member_until from public.rp_ai_wallets where user_id=u)<>expiry then raise exception 'approval replay extended';end if;checks:=checks+1;
 prior:=expiry;o:=public.rp_membership_create_order();order_id:=(o->>'id')::uuid;
 perform public.rp_membership_submit_order(order_id,now(),'renewal123');perform public.rp_membership_review_order(a,order_id,true,1290,'renew');
 select member_until into expiry from public.rp_ai_wallets where user_id=u;
 if expiry<>(((prior at time zone 'Asia/Shanghai')+interval '1 month') at time zone 'Asia/Shanghai') then raise exception 'renewal not extended';end if;checks:=checks+1;
 if ((timestamptz '2028-01-31 08:00+08' at time zone 'Asia/Shanghai')+interval '1 month')<>timestamp '2028-02-29 08:00' then raise exception 'month clamp failed';end if;checks:=checks+1;
 update public.rp_ai_wallets set remaining=0 where user_id=u;
 for i in 1..7 loop
  r:=gen_random_uuid();response:=public.rp_ai_reserve(u,r,'notes',1);
  if (response->>'charged')::boolean then raise exception 'member charged';end if;
  perform public.rp_ai_finish(u,r,true,'[]','{"answer":"synthetic"}');
 end loop;
 if (select remaining<>0 or unlimited from public.rp_ai_wallets where user_id=u) then raise exception 'member wallet mutated';end if;checks:=checks+1;
 r:=gen_random_uuid();perform public.rp_ai_reserve(u,r,'notes',1);
 update public.rp_ai_wallets set member_until=now()-interval '1 second' where user_id=u;
 perform public.rp_ai_finish(u,r,false,'[]',null);
 if (select remaining from public.rp_ai_wallets where user_id=u)<>0 then raise exception 'failure created free credit';end if;checks:=checks+1;
 begin perform public.rp_ai_reserve(u,gen_random_uuid(),'notes',1);raise exception 'expired member allowed';exception when raise_exception then if sqlerrm<>'NO_CREDITS' then raise;end if;end;checks:=checks+1;
 if has_function_privilege('authenticated','public.rp_membership_review_order(uuid,uuid,boolean,integer,text)','execute') or has_function_privilege('authenticated','public.rp_membership_admin_orders(uuid,text)','execute') then raise exception 'client admin RPC access';end if;checks:=checks+1;
 if has_table_privilege('authenticated','public.rp_membership_orders','update') or has_column_privilege('authenticated','public.rp_ai_wallets','member_until','update') then raise exception 'client may edit membership';end if;checks:=checks+1;
 execute 'set local role authenticated';
 select count(*) into n from public.rp_membership_orders;
 if n<>2 then raise exception 'owner order RLS failed';end if;checks:=checks+1;
 if public.rp_membership_is_admin() then raise exception 'ordinary user admin';end if;checks:=checks+1;
 begin perform 1 from public.rp_membership_admins;raise exception 'client reads admin registry';exception when insufficient_privilege then null;end;checks:=checks+1;
 execute 'reset role';
 perform set_config('request.jwt.claims',json_build_object('sub',v,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 select count(*) into n from public.rp_membership_orders;
 if n<>0 then raise exception 'cross user orders visible';end if;checks:=checks+1;
 execute 'reset role';
 perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 if not public.rp_membership_is_admin() then raise exception 'reviewer missing';end if;checks:=checks+1;
 execute 'reset role';
 if checks<>25 then raise exception 'incomplete checks %',checks;end if;
end $$;
select '25 passed, 0 failed; synthetic changes rolled back' as result;
rollback;
